function parseProbeSums(bytes){const map=new Map(); for(const line of bytes.toString('utf8').trim().split('\n')){const m=/^([a-f0-9]{64})\s+(.+)$/.exec(line); assert.ok(m,`invalid probe checksum line: ${line}`); assert.equal(map.has(m[2]),false,`duplicate probe checksum ${m[2]}`); map.set(m[2],m[1]);} return map;}
