    if(path==='package.json'){expected.packageManager='pnpm@11.18.0'; expected.engines??={}; expected.engines.node='24.18.1';}
    if(path==='apps/api/package.json'){expected.engines??={}; expected.engines.node='24.18.1';}
    assert.deepEqual(transformed,expected,`${path} has an unknown key, unauthorized value, script edit, or declaration drift`);
    assert.equal(Object.hasOwn(transformed,'rjc256_snapshot_id'),false,`${path} must not be snapshot-stamped`);
    for(const section of ['dependencies','devDependencies']) for(const [packageName,version] of Object.entries(transformed[section]??{})){if(String(version).startsWith('workspace:')) continue; const contextMap=MANIFEST_CONTEXT[path],context=typeof contextMap==='string'?contextMap:contextMap[section],row=childRows.get([path,section,packageName,context].join(' + ')); assert.ok(row,`${path} contains a declaration absent from the effective child: ${section}.${packageName}`); assert.equal(version,row.selected_version,`${path} declaration differs from the effective child: ${section}.${packageName}`);}
