  const dir=await mkdtemp(join(tmpdir(),'rjc256-v24-patch-')); try{for(const path of TRANSFORM_PATHS){const destination=join(dir,path); await mkdir(dirname(destination),{recursive:true}); await writeFile(destination,before[path]);} const patchPath=join(dir,'workspace-reduction.patch'); await writeFile(patchPath,patchBytes); await execFileAsync('git',['apply','--whitespace=nowarn',patchPath],{cwd:dir}); for(const path of TRANSFORM_PATHS) assert.deepEqual(await readFile(join(dir,path)),after[path],`post-patch drift for ${path}`);} finally {await rm(dir,{recursive:true});}
